css:
/* Public font files used by dinext.ru. */
@font-face {
  font-family: "Tilda Sans";
  src: url("https://static.tildacdn.com/fonts/tildasans/TildaSans-Regular.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: "Tilda Sans";
  src: url("https://static.tildacdn.com/fonts/tildasans/TildaSans-Semibold.woff2") format("woff2");
  font-style: normal;
  font-weight: 600 900;
  font-display: swap;
}

body[data-path="homepage"] {
  margin: 0;
  background: #f8f7fc;
}
body[data-path="homepage"] > nav.navbar,
body[data-path="homepage"] > footer.web-footer,
body[data-path="homepage"] #page-home-page .page-breadcrumbs,
body[data-path="homepage"] #page-home-page .page-header-wrapper,
body[data-path="homepage"] #page-home-page .page-footer { display: none !important; }
body[data-path="homepage"] #page-home-page .page-content-wrapper,
body[data-path="homepage"] #page-home-page .page_content,
body[data-path="homepage"] #page-home-page .webpage-content { margin: 0; padding: 0; }
body[data-path="homepage"] #home-page { text-align: left !important; }

#home-page .dinext-welcome {
  --ink: #252b49;
  --muted: #596079;
  --lavender: #f8f7fc;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  overflow-x: clip;
  background: radial-gradient(ellipse 50% 55% at 77% 39%, #ece5f8 0%, transparent 82%), #f8f7fc;
  color: var(--ink);
  font-family: "Tilda Sans", "Segoe UI", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}
#home-page .dinext-welcome *, #home-page .dinext-welcome *::before,
#home-page .dinext-welcome *::after { box-sizing: border-box; }
#home-page .dinext-welcome a { color: inherit; text-decoration: none; }
#home-page .dinext-welcome a:focus-visible {
  outline: 3px solid #b1325c;
  outline-offset: 5px;
  border-radius: 5px;
}
#home-page .welcome-shell { width: min(100% - 96px, 1220px); margin-inline: auto; }
#home-page .welcome-skip {
  position: absolute; left: 24px; top: -80px; z-index: 20;
  padding: 12px 16px; border-radius: 8px; background: #fff;
  box-shadow: 0 4px 18px #252b4929;
}
#home-page .welcome-skip:focus { top: 14px; }
#home-page .welcome-header { position: relative; z-index: 2; border-bottom: 1px solid #252b4915; }
#home-page .welcome-header-inner { min-height: clamp(68px, 9svh, 84px); display: flex; align-items: center; justify-content: space-between; gap: 24px; }
#home-page .welcome-brand { display: inline-flex; align-items: center; flex: none; }
#home-page .welcome-brand img { display: block; width: 164px; height: auto; }
#home-page .welcome-nav { display: flex; align-items: center; gap: 34px; font-size: 15px; font-weight: 650; }
#home-page .welcome-nav-docs, #home-page .welcome-nav-login { white-space: nowrap; }
#home-page .welcome-nav-docs:hover, #home-page .welcome-footer a:hover { color: #805795; }
#home-page .welcome-nav-docs span, #home-page .welcome-nav-login span,
#home-page .welcome-primary span, #home-page .welcome-help-link span,
#home-page .welcome-footer a span { margin-left: 5px; }
#home-page .welcome-nav-login { padding: 12px 22px; border: 1px solid #252b4938; border-radius: 999px; transition: background .2s, border-color .2s; }
#home-page .welcome-nav-login:hover { background: #ebe6f4; border-color: #805795; }

#home-page .welcome-main { flex: 1; display: flex; flex-direction: column; }
#home-page .welcome-hero { flex: 1; display: flex; align-items: center; }
#home-page .welcome-hero-grid { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr); align-items: center; gap: 30px; padding-block: clamp(10px, 3svh, 26px); }
#home-page .welcome-intro { position: relative; z-index: 1; max-width: 650px; }
#home-page .welcome-eyebrow { display: flex; align-items: center; gap: 12px; margin: 0 0 18px; color: #594a75; font-size: 14px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; }
#home-page .welcome-eyebrow-mark { width: 10px; height: 10px; flex: none; border-radius: 3px; background: #815995; transform: rotate(-30deg); }
#home-page .welcome-intro h1 { margin: 0; max-width: 710px; color: var(--ink); font-size: clamp(42px, 4.3vw, 62px); font-weight: 700; line-height: 1.08; letter-spacing: -.045em; }
#home-page .welcome-intro h1 span { display: block; color: #805795; }
#home-page .welcome-lead { max-width: 490px; margin: 20px 0 24px; color: var(--muted); font-size: clamp(17px, 1.45vw, 20px); line-height: 1.55; }
#home-page .welcome-primary {
  display: inline-flex; align-items: center; justify-content: space-between; gap: 22px;
  min-height: 56px; padding: 14px 23px 14px 26px; border-radius: 15px;
  background: linear-gradient(105deg, #252b49 0%, #805795 100%);
  box-shadow: 0 16px 30px #4c356837; color: #fff !important;
  font-size: 17px; font-weight: 700; line-height: 1.25; transition: transform .2s, box-shadow .2s;
}
#home-page .welcome-primary:hover { transform: translateY(-2px); box-shadow: 0 20px 35px #4c35684a; }
#home-page .welcome-primary span { font-size: 23px; font-weight: 400; line-height: .8; }
#home-page .welcome-caption { margin: 10px 0 0; color: #646b81; font-size: 13px; }

#home-page .welcome-art {
  position: relative;
  width: min(100%, 520px);
  height: clamp(260px, 47svh, 455px);
  margin-left: auto;
  isolation: isolate;
}
#home-page .welcome-art::before {
  content: "";
  position: absolute;
  inset: 8%;
  border-radius: 50%;
  background: radial-gradient(circle, #eae2f5aa 0%, #eae2f500 68%);
}
#home-page .welcome-art-orbit {
  position: absolute;
  inset: 15% 2%;
  border: 1px solid #ffffffb8;
  border-radius: 50%;
  transform: rotate(-30deg);
  box-shadow: 0 0 100px #ffffff80;
}
#home-page .welcome-art canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

#home-page .welcome-help { display: flex; align-items: center; gap: 18px; padding: 18px 24px; border: 1px solid #dfd8eb; border-radius: 20px; background: #ffffffbf; box-shadow: 0 15px 45px #5348770a; }
#home-page .welcome-help-icon { display: grid; place-items: center; width: 50px; height: 50px; flex: none; border-radius: 17px; background: #e9e0f3; color: #654a83; font-size: 32px; font-weight: 600; }
#home-page .welcome-help-copy { flex: 1; min-width: 0; }
#home-page .welcome-help-label { margin: 0 0 4px; color: #654a83; font-size: 11px; font-weight: 800; letter-spacing: .12em; }
#home-page .welcome-help h2 { margin: 0; color: var(--ink); font-size: 20px; font-weight: 700; line-height: 1.25; }
#home-page .welcome-help-copy > p:last-child { margin: 5px 0 0; color: var(--muted); font-size: 14px; line-height: 1.45; }
#home-page .welcome-help-link { display: inline-flex; align-items: center; justify-content: space-between; gap: 18px; flex: none; padding: 13px 16px; border: 1px solid #c4b6d6; border-radius: 11px; font-size: 14px; font-weight: 700; transition: background .2s; }
#home-page .welcome-help-link:hover { background: #f0ebf7; }
#home-page .welcome-help-link span { font-size: 19px; font-weight: 400; }
#home-page .welcome-footer { margin-top: clamp(8px, 2svh, 18px); border-top: 1px solid #252b4917; }
#home-page .welcome-footer-inner { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: clamp(52px, 7svh, 62px); color: #596079; font-size: 13px; }
#home-page .welcome-footer a { font-weight: 650; }

@media (max-width: 900px) {
  #home-page .welcome-shell { width: min(100% - 56px, 680px); }
  #home-page .welcome-hero-grid { grid-template-columns: 1fr; gap: 4px; padding-block: 36px 10px; }
  #home-page .welcome-intro { max-width: 650px; }
  #home-page .welcome-intro h1 { font-size: clamp(42px, 6.8vw, 58px); }
  #home-page .welcome-art { width: min(100%, 400px); height: clamp(225px, 33svh, 330px); margin-inline: auto; }
  #home-page .welcome-help { flex-wrap: wrap; }
  #home-page .welcome-help-link { margin-left: 72px; }
}
@media (max-width: 560px) {
  #home-page .welcome-shell { width: calc(100% - 40px); }
  #home-page .welcome-header-inner { min-height: 68px; }
  #home-page .welcome-brand img { width: 135px; }
  #home-page .welcome-nav { gap: 0; font-size: 14px; }
  #home-page .welcome-nav-docs { display: none; }
  #home-page .welcome-nav-login { padding: 9px 15px; }
  #home-page .welcome-hero-grid { padding-block: clamp(20px, 3svh, 28px) 4px; }
  #home-page .welcome-eyebrow { margin-bottom: 14px; font-size: 11px; letter-spacing: .07em; }
  #home-page .welcome-intro h1 { font-size: clamp(34px, 9.5vw, 42px); letter-spacing: -.045em; }
  #home-page .welcome-lead { margin: 16px 0 20px; font-size: 16px; }
  #home-page .welcome-primary { width: 100%; min-height: 54px; padding-inline: 18px; gap: 9px; font-size: 15px; }
  #home-page .welcome-art { width: min(100%, 325px); height: clamp(155px, 21svh, 205px); }
  #home-page .welcome-help { gap: 12px; padding: 15px 18px; border-radius: 16px; }
  #home-page .welcome-help-icon { width: 45px; height: 45px; border-radius: 12px; font-size: 26px; }
  #home-page .welcome-help-copy { flex-basis: calc(100% - 59px); }
  #home-page .welcome-help h2 { font-size: 17px; }
  #home-page .welcome-help-copy > p:last-child { font-size: 13px; }
  #home-page .welcome-help-link { margin: 4px 0 0; width: 100%; }
  #home-page .welcome-footer { margin-top: 0; }
  #home-page .welcome-footer-inner { min-height: 54px; }
}
@media (max-width: 340px) {
  #home-page .welcome-shell { width: calc(100% - 32px); }
  #home-page .welcome-brand img { width: 122px; }
  #home-page .welcome-intro h1 { font-size: 36px; }
}
@media (prefers-reduced-motion: reduce) {
  #home-page .dinext-welcome a { transition: none !important; }
}

